G=load()
def solve(a):
    L=[r[:4] for r in a[:4]]; R=[r[5:] for r in a[:4]]
    out=[r[:] for r in L]
    # find shape cells in R (nonzero, excluding 5-col boundary): color = that value
    cols=set(R[i][j] for i in range(4) for j in range(4) if R[i][j]!=0)
    if len(cols)==1 and next(iter(cols))!=1:
        c=next(iter(cols))
        if not any(R[i][j]==c and L[i][j]==1 for i in range(4) for j in range(4)):
            for i in range(4):
                for j in range(4):
                    if R[i][j]==c: out[i][j]=c
    return out
for k in ['Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4']:
